def register(name: str, parse: WebhookParser) -> None:
    @app.post(f"/webhook/{name}", name=f"webhook_{name}")
    async def receive(request: Request) -> JSONResponse:
        if config.WEBHOOK_TOKEN and request.headers.get("x-webhook-token") != config.WEBHOOK_TOKEN:
            raise HTTPException(status_code=401, detail="invalid or missing X-Webhook-Token")
        try:
            body: Any = await request.json()
        except Exception:
            raise HTTPException(status_code=422, detail="request body must be JSON") from None
        if not isinstance(body, dict):
            raise HTTPException(status_code=422, detail="request body must be a JSON object")
        try:
            intake = parse(dict(request.headers), body)
        except (InvalidWebhookError, ValidationError) as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from None
        if intake.request is None:
            return JSONResponse(intake.response or {"ok": True})
        try:
            receipt = await publish(intake.request)
        except QueueUnavailableError:
            raise HTTPException(status_code=503, detail="queue is not accepting messages") from None
        log.info("webhook/%s: queued %s", name, intake.request.external_id)
        return JSONResponse({"ok": True, "run": "queued", **receipt.model_dump()}, status_code=202)

lowered = {key.lower(): value for key, value in headers.items()}
event, delivery = lowered.get("x-github-event"), lowered.get("x-github-delivery")
if not event or not delivery:
    raise InvalidWebhookError("X-GitHub-Event and X-GitHub-Delivery headers are required")
payload: dict[str, Any] = {"headers": {key: lowered[key] for key in _ALLOWED_HEADERS if lowered.get(key)}, "body": body}
return WebhookIntake(EventRequest(provider="github", external_id=delivery, payload=payload))

if body.get("type") == "url_verification":
    return WebhookIntake(None, response={"challenge": body.get("challenge", "")})
event_id = body.get("event_id")
if not isinstance(event_id, str) or not event_id.strip():
    raise InvalidWebhookError("Slack event payload requires event_id")
return WebhookIntake(EventRequest(provider="slack", external_id=event_id, payload=without_token(body)))

async def _on_message(self, data: dict[str, Any]) -> None:
    author = data.get("author")
    if not isinstance(author, dict) or author.get("bot") or data.get("webhook_id") is not None or str(author.get("id")) != str(self._owner_id):
        return
    try:
        session_id, parent_session_id = await self._sessions(str(data["channel_id"]))
        await self._producer.publish(EventRequest(provider="discord", external_id=str(data["id"]), payload=data,
                                                        session_id=session_id, parent_session_id=parent_session_id))
    except Exception:
        log.exception("Discord message was not durably accepted (message=%s)", data.get("id"))

if channel_id == self._general:
    return None, None
session_id = await self._resolve_session("discord", channel_id)
channel = self._client.get_channel(int(channel_id)) if channel_id.isdecimal() else None
parent = getattr(channel, "parent_id", None)
if parent is None or str(parent) == self._general:
    return session_id, None
return session_id, await self._resolve_session("discord", str(parent))

try:
    event = socket_event(request.payload, team_id=self._team_id, channel_id=self._channel_id) if request.type == "events_api" else None
except Exception as exc:
    log.error("Slack event could not be read: %s", type(exc).__name__)
    event = None
if event is None:
    await self._ack(client, request.envelope_id)
    return
try:
    await self._producer.publish(event)
except Exception as exc:
    log.error("Slack event publication failed: %s", type(exc).__name__)
    return
await self._ack(client, request.envelope_id)

async def publish(self, request: EventRequest) -> PublishReceipt:
    """実行依頼を投入する。重複排除はしない。"""
    return await self.stream.publish(request.model_dump_json())

async def publish(self, data: str) -> PublishReceipt:
    try:
        message_id = str(await self.client.xadd(self.key, {"data": data}))
    except RedisError as exc:
        raise QueueUnavailableError("queue write could not be confirmed") from exc
    return PublishReceipt(message_id=message_id, accepted_at=int(message_id.split("-", 1)[0]) / 1000)

async def _read_loop(self) -> None:
    while not self._stopping.is_set():
        await self._slots.acquire()
        delivery = None
        try:
            if not self._stopping.is_set():
                delivery = await self.queue.next()
        except Exception:
            log.exception("queue read failed")
            with suppress(TimeoutError):
                await asyncio.wait_for(self._stopping.wait(), 1)
        if delivery is None or self._stopping.is_set():

entry = await self.stream.reclaim()
if entry is None:
    entry = await self.stream.read()
if entry is None:
    return None
if entry.deliveries > config.QUEUE_MAX_DELIVERIES:
    await self.stream.dead(entry, f"delivered {entry.deliveries} times")
    return None
try:
    request = EventRequest.model_validate_json(entry.data)
except (ValidationError, ValueError) as exc:
    await self.stream.dead(entry, f"invalid message: {exc}")
    return None
return entry.message_id, request

async def _run(self, run: RunVersions, request: EventRequest, message_id: str) -> AgentResult:
    # イベントの原形と投入側が決めた session だけを dispatch Agent へ渡す。中身は解釈しない。
    name, payload, parent_session_id = config.DISPATCH_AGENT, None, request.parent_session_id
    version = run.version(name)
    data: dict[str, Any] = {"event": {"provider": request.provider, "external_id": request.external_id, "payload": dict(request.payload)}}
    run_id = new_id()
    session_id = request.session_id or new_id()
    ctx = AgentContext(
        data=deepcopy(data), max_steps=self.max_steps, run_id=run_id, session_id=session_id,
        parent_session_id=parent_session_id, message_id=message_id, acknowledger=self.queue.ack, agents=run,
    )
    agent = version.graph.agents.get(name) if name in version.graph.entrances else None
    # session_run は入口の版で記録する。
    with component_scope(version.label):
        try:
            await self.sessions.begin_run(run_id, session_id, agent_name=name, data=data, request=payload, parent_session_id=parent_session_id)
        except Exception:
            log.exception("could not record the run start (run_id=%s)", run_id)
            return _failed("session", "could not record the run start")
        try:
            result = await self._call(agent, name, AgentCall(ctx=ctx, request=payload))
        except asyncio.CancelledError:
            cancelled = AgentResult(status="cancelled", errors=(ErrorNote("cancellation", "run cancelled by its caller"),))
            try:
                await self.sessions.finish_run(run_id, cancelled)
            except Exception:
                log.exception("could not record run cancellation (run_id=%s)", run_id)
            raise
        try:
            await self.sessions.finish_run(run_id, result)

async def _call(self, agent: Any, name: str, call: AgentCall) -> AgentResult:
    if agent is None:
        return _failed("entrance", f"unknown entrance: {name}")
    try:
        async with asyncio.timeout(config.RUN_TIMEOUT):
            result: AgentResult = await agent.run(call)
            return result
    except TimeoutError:
        return AgentResult(status="cancelled", errors=(ErrorNote("deadline", f"run exceeded {config.RUN_TIMEOUT:g}s"),))
    except Exception as exc:
        log.exception("agent failed (run_id=%s, agent=%s)", call.ctx.run_id, name)
        return _failed("execution", f"{type(exc).__name__}: {exc}")

created_at = self._clock()
while (commit := await self._store.write(files, parent, message, created_at)) is None:
    created_at += timedelta(seconds=1)
version = await self._load_in_thread(commit, files)
try:
    await self._store.keep(commit.id)
except BaseException:
